  vocab=[("área superficial", "medida de toda la superficie exterior de un cuerpo"), ("conjetura", "afirmación basada en observaciones, aún sin demostración"), ("aproximar π", "usar un valor cercano como 3,14 o 22/7"), ("circunferencia", "borde de un círculo, de largo 2πr"), ("en función de π", "dejar π escrito sin reemplazar por un decimal")],
